// Does the world's water shader still describe the pond in shared/ambientWater?
// Pure node — the emitters and the octave table, no Babylon, no GPU.
//
// The world renders the ambient surface on two renderers (WGSL + GLSL), both
// generated by shared/ambientWaterShader.js from the ONE octave table in
// shared/ambientWater.js. This asserts the generation actually reflects that
// table — same octave count, same wavelength/amplitude literals, same fine
// gate — and that each emitted language is structurally itself (no GLSL tokens
// leaking into the WGSL and vice versa), the same discipline the rock-material
// twin check applies. If someone edits an octave in ambientWater.js, the water
// the world draws moves with it, and this proves it did rather than trusting it.

import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

import { OCTAVES } from "../../shared/ambientWater.js";
import { ambientGLSL, ambientWGSL, SLOPE_GAIN } from "../../shared/ambientWaterShader.js";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
let failures = 0;
function check(name, ok, detail) {
    console.log((ok ? "ok   " : "FAIL ") + name + (ok || !detail ? "" : " — " + detail));
    if (!ok) failures++;
}
const balanced = (s, o, c) => (s.split(o).length === s.split(c).length);

const glsl = ambientGLSL();
const wgsl = ambientWGSL();

// ------------------------------------------------------------ tied to OCTAVES
for (let i = 0; i < OCTAVES.length; i++) {
    const [L, amp, dir] = OCTAVES[i];
    const dl = Math.hypot(dir[0], dir[1]);
    const nx = (dir[0] / dl).toString(), ny = (dir[1] / dl).toString();
    for (const [lang, src] of [["GLSL", glsl], ["WGSL", wgsl]]) {
        check(`${lang} carries octave ${i} wavelength ${L}`, src.includes(`${L} * S`));
        check(`${lang} carries octave ${i} amplitude ${amp}`, src.includes(`${amp} * W * S`));
        check(`${lang} carries octave ${i} direction`, src.includes(nx) && src.includes(ny),
            `expected ${nx}, ${ny}`);
    }
}
for (const [lang, src] of [["GLSL", glsl], ["WGSL", wgsl]]) {
    // The fine gate is on the two SHORT octaves only (index >= 2), as the lab.
    const fineHits = (src.match(/\* fine/g) || []).length;
    check(`${lang} gates exactly the two short octaves with fine`, fineHits === 2,
        `found ${fineHits}`);
    check(`${lang} defines SLOPE_GAIN = ${SLOPE_GAIN}`, src.includes(String(SLOPE_GAIN)));
    check(`${lang} exposes ambientField`, src.includes("ambientField"));
    check(`${lang} exposes ambientLostVariance`, src.includes("ambientLostVariance"));
    check(`${lang} braces balance`, balanced(src, "{", "}"));
    check(`${lang} parens balance`, balanced(src, "(", ")"));
}

// ------------------------------------------------------- each language is itself
check("GLSL is free of WGSL fn decls", !/\bfn\s+\w+\s*\(/.test(glsl));
check("GLSL is free of vec3f", !glsl.includes("vec3f"));
check("GLSL is free of ->", !glsl.includes("->"));
check("WGSL is free of gl_", !wgsl.includes("gl_"));
check("WGSL is free of texture2D(", !wgsl.includes("texture2D("));
check("WGSL uses vec3f, not GLSL vec3(", wgsl.includes("vec3f") && !/\bvec3\(/.test(wgsl));

// --------------------------------------------------- the shaders use the include
const waterVert = readFileSync(join(ROOT, "src/shaders/water.vertex.wgsl"), "utf8");
const waterFrag = readFileSync(join(ROOT, "src/shaders/water.fragment.wgsl"), "utf8");
check("water.vertex.wgsl includes ambientWater", waterVert.includes("#include<ambientWater>"));
check("water.fragment.wgsl includes ambientWater", waterFrag.includes("#include<ambientWater>"));
check("water.fragment.wgsl samples the reflection", waterFrag.includes("reflectionTex"));
check("water.fragment.wgsl pairs texture with its sampler",
    waterFrag.includes("reflectionTexSampler"));

// Shore treatment must exist in BOTH the WGSL fragment and the GLSL twin
// (registry.js), since they are hand-mirrored rather than emitted.
const registry = readFileSync(join(ROOT, "src/shaders/registry.js"), "utf8");
for (const [where, src] of [["WGSL fragment", waterFrag], ["GLSL twin", registry]]) {
    check(`${where} derives a shore distance`, src.includes("shoreDist"));
    check(`${where} reads the pond centre`, src.includes("pondCenter"));
    check(`${where} ramps depth by the foreshore slope`, src.includes("foreshoreSlope"));
    check(`${where} draws a foam lip`, src.includes("foam"));
    check(`${where} rides the shore line on the wave height`, src.includes("- amb.x"));
}

console.log(failures ? `\n${failures} failure(s)` : "\nall good");
process.exit(failures ? 1 : 0);
